-- A small stand-in for the Roblox engine, used only by tools/sim.js to run the game's
-- scripts outside Roblox and catch mistakes (wrong property names, missing values,
-- broken quest logic). It checks every class, property, method and enum against the
-- real API description exported from Roblox Studio.
-- Expects globals API_CLASSES and API_ENUMS (generated by sim.js).

local Mock = { errors = 0, stubs = {}, now = 0, terrain = {} }

local function fail(msg, level)
	error(msg, (level or 1) + 1)
end

----------------------------------------------------------------------
-- Luau library additions
----------------------------------------------------------------------
math.clamp = function(v, lo, hi)
	if v < lo then return lo end
	if v > hi then return hi end
	return v
end
math.round = function(v) return math.floor(v + 0.5) end
math.atan2 = function(y, x) return math.atan(y, x) end
math.pow = nil
table.find = function(t, v)
	for i, x in ipairs(t) do if x == v then return i end end
	return nil
end
table.clone = function(t)
	local c = {}
	for k, v in pairs(t) do c[k] = v end
	return c
end
unpack = table.unpack
string.split = function(s, sep)
	local out = {}
	for piece in string.gmatch(s, "([^" .. sep .. "]*)") do table.insert(out, piece) end
	return out
end
function warn(...)
	local parts = {}
	for i = 1, select("#", ...) do parts[#parts + 1] = tostring((select(i, ...))) end
	local text = table.concat(parts, " ")
	print("  WARN: " .. text)
	Mock.warnings = (Mock.warnings or 0) + 1
end
local realRandom = math.random
math.random = function(a, b)
	if a == nil then return realRandom() end
	if b == nil then return realRandom(math.floor(a)) end
	return realRandom(math.floor(a), math.floor(b))
end
os.clock = function() return Mock.now end
tick = function() return Mock.now end
time = function() return Mock.now end

----------------------------------------------------------------------
-- Value types
----------------------------------------------------------------------
local TYPE = setmetatable({}, { __mode = "k" })
local function tag(t, name) TYPE[t] = name return t end
function typeof(v)
	local t = type(v)
	if t == "table" then return TYPE[v] or "table" end
	return t
end

local function num(v, what)
	if type(v) ~= "number" then fail((what or "value") .. " must be a number, got " .. typeof(v), 3) end
	if v ~= v then fail((what or "value") .. " is NaN", 3) end
	return v
end

-- Vector3
local V3 = {}
V3.__index = function(self, k)
	if k == "X" then return rawget(self, 1) elseif k == "Y" then return rawget(self, 2) elseif k == "Z" then return rawget(self, 3) end
	if k == "Magnitude" then return math.sqrt(self[1] ^ 2 + self[2] ^ 2 + self[3] ^ 2) end
	if k == "Unit" then
		local m = math.sqrt(self[1] ^ 2 + self[2] ^ 2 + self[3] ^ 2)
		if m == 0 then fail("Unit of a zero-length Vector3 (would be NaN in Roblox)", 2) end
		return Vector3.new(self[1] / m, self[2] / m, self[3] / m)
	end
	if V3[k] then return V3[k] end
	fail(tostring(k) .. " is not a valid member of Vector3", 2)
end
Vector3 = {}
function Vector3.new(x, y, z)
	return tag(setmetatable({ num(x or 0, "X"), num(y or 0, "Y"), num(z or 0, "Z") }, V3), "Vector3")
end
local function isV3(v) return TYPE[v] == "Vector3" end
V3.__add = function(a, b) if not isV3(a) or not isV3(b) then fail("Vector3 + " .. typeof(isV3(a) and b or a), 2) end return Vector3.new(a[1] + b[1], a[2] + b[2], a[3] + b[3]) end
V3.__sub = function(a, b) if not isV3(a) or not isV3(b) then fail("Vector3 - " .. typeof(isV3(a) and b or a), 2) end return Vector3.new(a[1] - b[1], a[2] - b[2], a[3] - b[3]) end
V3.__mul = function(a, b)
	if type(a) == "number" then return Vector3.new(a * b[1], a * b[2], a * b[3]) end
	if type(b) == "number" then return Vector3.new(a[1] * b, a[2] * b, a[3] * b) end
	if isV3(a) and isV3(b) then return Vector3.new(a[1] * b[1], a[2] * b[2], a[3] * b[3]) end
	fail("bad Vector3 multiplication", 2)
end
V3.__div = function(a, b)
	if type(b) == "number" then return Vector3.new(a[1] / b, a[2] / b, a[3] / b) end
	fail("bad Vector3 division", 2)
end
V3.__unm = function(a) return Vector3.new(-a[1], -a[2], -a[3]) end
V3.__eq = function(a, b) return a[1] == b[1] and a[2] == b[2] and a[3] == b[3] end
V3.__tostring = function(a) return string.format("%.2f, %.2f, %.2f", a[1], a[2], a[3]) end
function V3.Dot(a, b) return a[1] * b[1] + a[2] * b[2] + a[3] * b[3] end
function V3.Cross(a, b) return Vector3.new(a[2] * b[3] - a[3] * b[2], a[3] * b[1] - a[1] * b[3], a[1] * b[2] - a[2] * b[1]) end
function V3.Lerp(a, b, t) return a + (b - a) * t end
Vector3.zero = Vector3.new(0, 0, 0)
Vector3.one = Vector3.new(1, 1, 1)
Vector3.xAxis = Vector3.new(1, 0, 0)
Vector3.yAxis = Vector3.new(0, 1, 0)
Vector3.zAxis = Vector3.new(0, 0, 1)

-- Vector2
local V2 = {}
V2.__index = function(self, k)
	if k == "X" then return rawget(self, 1) elseif k == "Y" then return rawget(self, 2) end
	if k == "Magnitude" then return math.sqrt(self[1] ^ 2 + self[2] ^ 2) end
	fail(tostring(k) .. " is not a valid member of Vector2", 2)
end
V2.__add = function(a, b) return Vector2.new(a[1] + b[1], a[2] + b[2]) end
V2.__sub = function(a, b) return Vector2.new(a[1] - b[1], a[2] - b[2]) end
Vector2 = {}
function Vector2.new(x, y) return tag(setmetatable({ num(x or 0), num(y or 0) }, V2), "Vector2") end
Vector2.zero = Vector2.new(0, 0)

-- CFrame: position p and rotation matrix m (row-major, 9 numbers)
local CF = {}
CFrame = {}
local function mk(px, py, pz, m)
	if px ~= px or py ~= py or pz ~= pz then fail("CFrame with NaN position", 3) end
	for i = 1, 9 do if m[i] ~= m[i] then fail("CFrame with NaN rotation", 3) end end
	return tag(setmetatable({ px = px, py = py, pz = pz, m = m }, CF), "CFrame")
end
local IDENT = { 1, 0, 0, 0, 1, 0, 0, 0, 1 }
local function mmul(a, b)
	local r = {}
	for i = 0, 2 do
		for j = 0, 2 do
			r[i * 3 + j + 1] = a[i * 3 + 1] * b[j + 1] + a[i * 3 + 2] * b[3 + j + 1] + a[i * 3 + 3] * b[6 + j + 1]
		end
	end
	return r
end
local function mvec(m, x, y, z)
	return m[1] * x + m[2] * y + m[3] * z, m[4] * x + m[5] * y + m[6] * z, m[7] * x + m[8] * y + m[9] * z
end
function CFrame.new(a, b, c, ...)
	if a == nil then return mk(0, 0, 0, IDENT) end
	if isV3(a) then
		if b == nil then return mk(a[1], a[2], a[3], IDENT) end
		if not isV3(b) then fail("CFrame.new(Vector3, " .. typeof(b) .. ")", 2) end
		local f = b - a
		if f.Magnitude < 1e-6 then fail("CFrame.new(pos, lookAt) with identical points", 2) end
		f = f.Unit
		local up = Vector3.new(0, 1, 0)
		local r = f:Cross(up)
		if r.Magnitude < 1e-6 then r = Vector3.new(1, 0, 0) else r = r.Unit end
		local u = r:Cross(f)
		return mk(a[1], a[2], a[3], { r[1], u[1], -f[1], r[2], u[2], -f[2], r[3], u[3], -f[3] })
	end
	if select("#", ...) > 0 then fail("CFrame.new with matrix components is not supported by the mock", 2) end
	return mk(num(a, "x"), num(b, "y"), num(c, "z"), IDENT)
end
function CFrame.lookAt(a, b) return CFrame.new(a, b) end
function CFrame.Angles(rx, ry, rz)
	num(rx, "rx") num(ry, "ry") num(rz, "rz")
	local cx, sx, cy, sy, cz, sz = math.cos(rx), math.sin(rx), math.cos(ry), math.sin(ry), math.cos(rz), math.sin(rz)
	local X = { 1, 0, 0, 0, cx, -sx, 0, sx, cx }
	local Y = { cy, 0, sy, 0, 1, 0, -sy, 0, cy }
	local Z = { cz, -sz, 0, sz, cz, 0, 0, 0, 1 }
	return mk(0, 0, 0, mmul(mmul(X, Y), Z))
end
CFrame.fromEulerAnglesXYZ = CFrame.Angles
CFrame.identity = mk(0, 0, 0, IDENT)
CF.__index = function(self, k)
	if k == "Position" or k == "p" then return Vector3.new(self.px, self.py, self.pz) end
	if k == "X" then return self.px elseif k == "Y" then return self.py elseif k == "Z" then return self.pz end
	local m = rawget(self, "m")
	if k == "LookVector" then return Vector3.new(-m[3], -m[6], -m[9]) end
	if k == "RightVector" then return Vector3.new(m[1], m[4], m[7]) end
	if k == "UpVector" then return Vector3.new(m[2], m[5], m[8]) end
	if k == "Rotation" then return mk(0, 0, 0, m) end
	if CF[k] then return CF[k] end
	fail(tostring(k) .. " is not a valid member of CFrame", 2)
end
CF.__mul = function(a, b)
	if TYPE[a] ~= "CFrame" then fail("cannot multiply " .. typeof(a) .. " by CFrame", 2) end
	if TYPE[b] == "CFrame" then
		local x, y, z = mvec(a.m, b.px, b.py, b.pz)
		return mk(a.px + x, a.py + y, a.pz + z, mmul(a.m, b.m))
	elseif isV3(b) then
		local x, y, z = mvec(a.m, b[1], b[2], b[3])
		return Vector3.new(a.px + x, a.py + y, a.pz + z)
	end
	fail("CFrame * " .. typeof(b), 2)
end
CF.__add = function(a, b) if not isV3(b) then fail("CFrame + " .. typeof(b), 2) end return mk(a.px + b[1], a.py + b[2], a.pz + b[3], a.m) end
CF.__sub = function(a, b) if not isV3(b) then fail("CFrame - " .. typeof(b), 2) end return mk(a.px - b[1], a.py - b[2], a.pz - b[3], a.m) end
function CF.Inverse(a)
	local m = a.m
	local t = { m[1], m[4], m[7], m[2], m[5], m[8], m[3], m[6], m[9] }
	local x, y, z = mvec(t, -a.px, -a.py, -a.pz)
	return mk(x, y, z, t)
end
function CF.ToWorldSpace(a, b) return a * b end
function CF.ToObjectSpace(a, b) return a:Inverse() * b end
function CF.PointToWorldSpace(a, v) return a * v end
function CF.Lerp(a, b, t) return mk(a.px + (b.px - a.px) * t, a.py + (b.py - a.py) * t, a.pz + (b.pz - a.pz) * t, (t >= 0.5) and b.m or a.m) end
function CF.GetComponents(a) return a.px, a.py, a.pz, table.unpack(a.m) end

-- Color3
local C3 = {}
C3.__index = function(self, k)
	if k == "R" then return rawget(self, 1) elseif k == "G" then return rawget(self, 2) elseif k == "B" then return rawget(self, 3) end
	if C3[k] then return C3[k] end
	fail(tostring(k) .. " is not a valid member of Color3", 2)
end
Color3 = {}
function Color3.new(r, g, b) return tag(setmetatable({ num(r or 0), num(g or 0), num(b or 0) }, C3), "Color3") end
function Color3.fromRGB(r, g, b)
	num(r, "r") num(g, "g") num(b, "b")
	if r < 0 or r > 255 or g < 0 or g > 255 or b < 0 or b > 255 then fail("Color3.fromRGB out of range", 2) end
	return Color3.new(r / 255, g / 255, b / 255)
end
function Color3.fromHSV(h, s, v) return Color3.new(v, v, v) end
function C3.Lerp(a, b, t) return Color3.new(a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t, a[3] + (b[3] - a[3]) * t) end

-- UDim / UDim2
UDim = {}
function UDim.new(s, o) return tag({ Scale = num(s or 0), Offset = num(o or 0) }, "UDim") end
UDim2 = {}
function UDim2.new(xs, xo, ys, yo)
	return tag({ X = UDim.new(xs or 0, xo or 0), Y = UDim.new(ys or 0, yo or 0) }, "UDim2")
end
function UDim2.fromScale(x, y) return UDim2.new(x, 0, y, 0) end
function UDim2.fromOffset(x, y) return UDim2.new(0, x, 0, y) end

NumberRange = {}
function NumberRange.new(a, b) num(a) return tag({ Min = a, Max = b or a }, "NumberRange") end
NumberSequenceKeypoint = {}
function NumberSequenceKeypoint.new(t, v, e) num(t) num(v) return tag({ Time = t, Value = v, Envelope = e or 0 }, "NumberSequenceKeypoint") end
NumberSequence = {}
function NumberSequence.new(a, b)
	if type(a) == "table" and TYPE[a] == nil then
		for i, k in ipairs(a) do
			if TYPE[k] ~= "NumberSequenceKeypoint" then fail("NumberSequence keypoint " .. i .. " is not a keypoint", 2) end
		end
		if a[1].Time ~= 0 or a[#a].Time ~= 1 then fail("NumberSequence must start at time 0 and end at time 1", 2) end
		for i = 2, #a do if a[i].Time < a[i - 1].Time then fail("NumberSequence keypoints must be in order", 2) end end
	else
		num(a)
	end
	return tag({ Keypoints = a }, "NumberSequence")
end
ColorSequenceKeypoint = {}
function ColorSequenceKeypoint.new(t, c)
	num(t)
	if TYPE[c] ~= "Color3" then fail("ColorSequenceKeypoint needs a Color3", 2) end
	return tag({ Time = t, Value = c }, "ColorSequenceKeypoint")
end
ColorSequence = {}
function ColorSequence.new(a, b)
	if TYPE[a] == "Color3" then
		if b ~= nil and TYPE[b] ~= "Color3" then fail("ColorSequence.new second colour is not a Color3", 2) end
	elseif type(a) == "table" then
		for i, k in ipairs(a) do
			if TYPE[k] ~= "ColorSequenceKeypoint" then fail("ColorSequence keypoint " .. i .. " is not a keypoint", 2) end
		end
		if a[1].Time ~= 0 or a[#a].Time ~= 1 then fail("ColorSequence must start at time 0 and end at time 1", 2) end
	else
		fail("ColorSequence.new needs a Color3 or keypoints", 2)
	end
	return tag({ Keypoints = a }, "ColorSequence")
end

-- Enum
local enumItems = {}
local EnumItemMT = { __tostring = function(self) return "Enum." .. self.EnumType .. "." .. self.Name end }
local EnumTypeMT = {
	__index = function(self, k)
		local items = enumItems[rawget(self, "__name")]
		if items[k] then return items[k] end
		fail(tostring(k) .. " is not a valid member of Enum." .. rawget(self, "__name"), 2)
	end,
}
local enumTypes = {}
for name, items in pairs(API_ENUMS) do
	enumItems[name] = {}
	for _, item in ipairs(items) do
		enumItems[name][item] = tag(setmetatable({ Name = item, EnumType = name }, EnumItemMT), "EnumItem")
	end
	enumTypes[name] = setmetatable({ __name = name }, EnumTypeMT)
end
Enum = setmetatable({}, {
	__index = function(_, k)
		if enumTypes[k] then return enumTypes[k] end
		fail(tostring(k) .. " is not a valid Enum", 2)
	end,
})

TweenInfo = {}
function TweenInfo.new(t, style, dir, rep, rev, delay)
	if t ~= nil then num(t, "time") end
	if style ~= nil and (TYPE[style] ~= "EnumItem" or style.EnumType ~= "EasingStyle") then fail("TweenInfo easing style is wrong", 2) end
	if dir ~= nil and (TYPE[dir] ~= "EnumItem" or dir.EnumType ~= "EasingDirection") then fail("TweenInfo easing direction is wrong", 2) end
	return tag({ Time = t or 1 }, "TweenInfo")
end

Random = {}
local RandomMT = { __index = {} }
function Random.new(seed)
	return tag(setmetatable({ s = (seed or 12345) % 2147483647 }, RandomMT), "Random")
end
local function nextRaw(self)
	self.s = (self.s * 48271) % 2147483647
	return self.s / 2147483647
end
function RandomMT.__index.NextNumber(self, a, b)
	local r = nextRaw(self)
	if a == nil then return r end
	num(a) num(b)
	return a + (b - a) * r
end
function RandomMT.__index.NextInteger(self, a, b)
	if math.type(a) ~= "integer" and a ~= math.floor(a) then fail("NextInteger needs whole numbers", 2) end
	if b < a then fail("NextInteger: max below min", 2) end
	return math.floor(a + nextRaw(self) * (b - a + 1) - 1e-9)
end

----------------------------------------------------------------------
-- Scheduler (task library, simulated time)
----------------------------------------------------------------------
local waiting = {}
local function report(co, err)
	Mock.errors = Mock.errors + 1
	print("  ERROR: " .. tostring(err))
	print(debug.traceback(co, "", 0))
end
local function resume(co, ...)
	local ok, a, b = coroutine.resume(co, ...)
	if not ok then
		report(co, a)
		return
	end
	if coroutine.status(co) == "suspended" then
		if a == "wait" then
			table.insert(waiting, { co = co, at = Mock.now + (b or 0), start = Mock.now })
		end
		-- "signal" waits are resumed by the signal itself
	end
end
task = {}
function task.spawn(fn, ...)
	if type(fn) ~= "function" then fail("task.spawn needs a function", 2) end
	local co = coroutine.create(fn)
	resume(co, ...)
	return co
end
function task.defer(fn, ...)
	local args = table.pack(...)
	table.insert(waiting, { co = coroutine.create(function() fn(table.unpack(args, 1, args.n)) end), at = Mock.now, start = Mock.now })
end
function task.delay(t, fn, ...)
	num(t, "delay")
	if type(fn) ~= "function" then fail("task.delay needs a function", 2) end
	local args = table.pack(...)
	table.insert(waiting, { co = coroutine.create(function() fn(table.unpack(args, 1, args.n)) end), at = Mock.now + t, start = Mock.now })
end
function task.wait(t)
	if t ~= nil then num(t, "wait time") end
	local elapsed = coroutine.yield("wait", math.max(t or 0, 0.03))
	return elapsed or (t or 0.03)
end
wait = nil
spawn = nil
delay = nil

----------------------------------------------------------------------
-- Signals
----------------------------------------------------------------------
local SignalMT = { __index = {} }
local function newSignal(name)
	return tag(setmetatable({ name = name, conns = {}, waiters = {} }, SignalMT), "RBXScriptSignal")
end
function SignalMT.__index.Connect(self, fn)
	if type(fn) ~= "function" then fail("Connect needs a function (" .. tostring(self.name) .. ")", 2) end
	local c = { fn = fn, Connected = true }
	function c.Disconnect(conn) conn.Connected = false end
	table.insert(self.conns, c)
	return c
end
SignalMT.__index.Once = SignalMT.__index.Connect
function SignalMT.__index.Wait(self)
	table.insert(self.waiters, coroutine.running())
	return coroutine.yield("signal")
end
local function fire(self, ...)
	for _, c in ipairs({ table.unpack(self.conns) }) do
		if c.Connected then task.spawn(c.fn, ...) end
	end
	local ws = self.waiters
	self.waiters = {}
	for _, co in ipairs(ws) do resume(co, ...) end
end
Mock.fire = fire
Mock.newSignal = newSignal

----------------------------------------------------------------------
-- Instances
----------------------------------------------------------------------
local Inst = {}
local data = setmetatable({}, { __mode = "k" })
local tags = {}
local tagSignals = {}
local methods = {}
local classMethods = {}

local function classInfo(name)
	return API_CLASSES[name]
end
local memberCache = {}
local function member(class, key)
	local c = memberCache[class]
	if not c then c = {} memberCache[class] = c end
	local hit = c[key]
	if hit ~= nil then return hit or nil end
	local cur = class
	while cur do
		local info = classInfo(cur)
		if not info then break end
		local m = info.m[key]
		if m then c[key] = m return m end
		cur = info.s
	end
	c[key] = false
	return nil
end
local function isA(class, base)
	local cur = class
	while cur do
		if cur == base then return true end
		local info = classInfo(cur)
		cur = info and info.s or nil
	end
	return false
end
Mock.isA = isA

local DEFAULTS = {
	bool = false, int = 0, int64 = 0, float = 0, double = 0, string = "",
}
local SPECIAL = {
	Humanoid = { Health = 100, MaxHealth = 100, WalkSpeed = 16, HipHeight = 2 },
	Players = { RespawnTime = 5 },
	Camera = {},
	ProximityPrompt = { Enabled = true },
	ParticleEmitter = { Enabled = true },
	PointLight = { Enabled = true },
	BillboardGui = { Enabled = true },
	GuiObject = { Visible = true },
}
local function defaultFor(class, key, m)
	local cur = class
	while cur do
		local s = SPECIAL[cur]
		if s and s[key] ~= nil then return s[key] end
		local info = classInfo(cur)
		cur = info and info.s or nil
	end
	local cat, typ = m.cat, m.typ
	if cat == "Primitive" then return DEFAULTS[typ] end
	if cat == "Enum" then
		local items = API_ENUMS[typ]
		return items and enumItems[typ][items[1]] or nil
	end
	if cat == "Class" then return nil end
	if typ == "Vector3" then return (key == "Size") and Vector3.new(4, 1, 2) or Vector3.zero end
	if typ == "CFrame" then return CFrame.identity end
	if typ == "Color3" then return Color3.new(1, 1, 1) end
	if typ == "UDim2" then return UDim2.new(0, 0, 0, 0) end
	if typ == "UDim" then return UDim.new(0, 0) end
	if typ == "Vector2" then return Vector2.zero end
	return nil
end

local function checkType(class, key, m, value)
	local cat, typ = m.cat, m.typ
	local got = typeof(value)
	if cat == "Primitive" then
		if typ == "bool" then
			if got ~= "boolean" then return "a true/false value" end
		elseif typ == "string" then
			if got ~= "string" then return "text" end
		elseif got ~= "number" then
			return "a number"
		elseif value ~= value then
			return "a real number (got NaN)"
		end
	elseif cat == "Enum" then
		if got ~= "EnumItem" or value.EnumType ~= typ then return "Enum." .. typ end
	elseif cat == "Class" then
		if value ~= nil and (got ~= "Instance" or not isA(data[value].class, typ)) then return "a " .. typ end
	elseif cat == "DataType" then
		if typ == "Content" or typ == "ContentId" then
			if got ~= "string" then return "text" end
		elseif typ == "Vector3" or typ == "CFrame" or typ == "Color3" or typ == "UDim2" or typ == "UDim" or typ == "Vector2"
			or typ == "NumberRange" or typ == "NumberSequence" or typ == "ColorSequence" then
			if got ~= typ then return typ end
		end
	end
	return nil
end

local function describe(inst)
	local d = data[inst]
	return d and (d.class .. " \"" .. tostring(d.props.Name) .. "\"") or "?"
end

local function sig(inst, name)
	local d = data[inst]
	local s = d.signals[name]
	if not s then s = newSignal(d.class .. "." .. name) d.signals[name] = s end
	return s
end
Mock.sig = sig

local function setParent(inst, parent)
	local d = data[inst]
	if d.destroyed and parent ~= nil then fail("The Parent property of " .. describe(inst) .. " is locked (it was destroyed)", 3) end
	local old = d.parent
	if old == parent then return end
	if old then
		local list = data[old].children
		for i, c in ipairs(list) do if c == inst then table.remove(list, i) break end end
	end
	d.parent = parent
	if parent then
		table.insert(data[parent].children, inst)
		fire(sig(parent, "ChildAdded"), inst)
	end
end

local InstMT = {}
InstMT.__index = function(self, key)
	local d = data[self]
	if key == "Parent" then return d.parent end
	if key == "ClassName" then return d.class end
	local v = d.props[key]
	if v ~= nil then return v end
	local m = member(d.class, key)
	if m then
		if m.k == "P" then
			if key == "Position" and d.props.CFrame then return d.props.CFrame.Position end
			if key == "PrimaryPart" then return nil end
			if m.cat == "Class" then
				for _, c in ipairs(d.children) do
					if data[c].props.Name == key then return c end
				end
				return nil
			end
			return defaultFor(d.class, key, m)
		elseif m.k == "E" then
			return sig(self, key)
		elseif m.k == "F" then
			local cur = d.class
			while cur do
				local cm = classMethods[cur]
				if cm and cm[key] then return cm[key] end
				local info = classInfo(cur)
				cur = info and info.s or nil
			end
			if methods[key] then return methods[key] end
			local label = d.class .. ":" .. key
			Mock.stubs[label] = (Mock.stubs[label] or 0) + 1
			return function() return nil end
		end
	end
	for _, c in ipairs(d.children) do
		if data[c].props.Name == key then return c end
	end
	fail(tostring(key) .. " is not a valid member of " .. describe(self), 2)
end
InstMT.__newindex = function(self, key, value)
	local d = data[self]
	if key == "Parent" then
		if value ~= nil and typeof(value) ~= "Instance" then fail("Parent must be an Instance", 2) end
		setParent(self, value)
		return
	end
	local m = member(d.class, key)
	if m and m.k == "C" then
		if value ~= nil and type(value) ~= "function" then fail(tostring(key) .. " of " .. describe(self) .. " must be a function", 2) end
		d.callbacks = d.callbacks or {}
		d.callbacks[key] = value
		return
	end
	if not m or m.k ~= "P" then fail(tostring(key) .. " is not a valid property of " .. describe(self), 2) end
	if m.ro then fail(tostring(key) .. " of " .. describe(self) .. " cannot be set (read only)", 2) end
	if value == nil and m.cat ~= "Class" then fail("cannot set " .. key .. " of " .. describe(self) .. " to nil", 2) end
	local problem = checkType(d.class, key, m, value)
	if problem then fail(key .. " of " .. describe(self) .. " must be " .. problem .. ", got " .. typeof(value) .. " (" .. tostring(value) .. ")", 2) end
	if key == "Position" and isA(d.class, "BasePart") then
		local cf = d.props.CFrame or CFrame.identity
		d.props.CFrame = mk(value[1], value[2], value[3], cf.m)
	else
		d.props[key] = value
	end
	local ps = d.propSignals and d.propSignals[key]
	if ps then fire(ps) end
end
InstMT.__tostring = function(self) return tostring(data[self].props.Name) end

local function create(class)
	local info = classInfo(class)
	if not info then fail("Unable to create an Instance of type \"" .. tostring(class) .. "\"", 3) end
	local inst = setmetatable({}, InstMT)
	TYPE[inst] = "Instance"
	data[inst] = { class = class, props = { Name = class }, children = {}, signals = {}, attrs = {} }
	return inst
end
Mock.create = create
Mock.data = data

Instance = {}
function Instance.new(class, parent)
	local info = classInfo(class)
	if not info then fail("Unable to create an Instance of type \"" .. tostring(class) .. "\"", 2) end
	if info.t:find("NotCreatable", 1, true) then fail(class .. " cannot be created with Instance.new", 2) end
	local inst = create(class)
	if parent then inst.Parent = parent end
	return inst
end

-- Methods shared by every instance
function methods.IsA(self, class)
	if not classInfo(class) then fail("IsA: \"" .. tostring(class) .. "\" is not a class", 2) end
	return isA(data[self].class, class)
end
function methods.GetChildren(self) return { table.unpack(data[self].children) } end
function methods.GetDescendants(self)
	local out = {}
	local function walk(i)
		for _, c in ipairs(data[i].children) do out[#out + 1] = c walk(c) end
	end
	walk(self)
	return out
end
function methods.FindFirstChild(self, name, recursive)
	if type(name) ~= "string" then fail("FindFirstChild needs a name", 2) end
	for _, c in ipairs(data[self].children) do
		if data[c].props.Name == name then return c end
	end
	if recursive then
		for _, c in ipairs(methods.GetDescendants(self)) do
			if data[c].props.Name == name then return c end
		end
	end
	return nil
end
function methods.WaitForChild(self, name, timeout)
	local c = methods.FindFirstChild(self, name)
	if c then return c end
	if timeout then return nil end
	fail("WaitForChild(\"" .. tostring(name) .. "\") on " .. describe(self) .. " would wait forever", 2)
end
function methods.FindFirstChildOfClass(self, class)
	if not classInfo(class) then fail("FindFirstChildOfClass: \"" .. tostring(class) .. "\" is not a class", 2) end
	for _, c in ipairs(data[self].children) do
		if data[c].class == class then return c end
	end
	return nil
end
function methods.FindFirstChildWhichIsA(self, class)
	if not classInfo(class) then fail("FindFirstChildWhichIsA: \"" .. tostring(class) .. "\" is not a class", 2) end
	for _, c in ipairs(data[self].children) do
		if isA(data[c].class, class) then return c end
	end
	return nil
end
function methods.IsDescendantOf(self, other)
	local cur = data[self].parent
	while cur do
		if cur == other then return true end
		cur = data[cur].parent
	end
	return false
end
function methods.Destroy(self)
	local d = data[self]
	if d.destroyed then return end
	fire(sig(self, "Destroying"))
	setParent(self, nil)
	d.destroyed = true
	for _, c in ipairs({ table.unpack(d.children) }) do methods.Destroy(c) end
	for t in pairs(d.tags or {}) do
		if tags[t] then tags[t][self] = nil end
	end
end
function methods.ClearAllChildren(self)
	for _, c in ipairs({ table.unpack(data[self].children) }) do methods.Destroy(c) end
end
function methods.Clone(self)
	local function copy(i)
		local d = data[i]
		local n = create(d.class)
		local nd = data[n]
		for k, v in pairs(d.props) do nd.props[k] = v end
		for k, v in pairs(d.attrs) do nd.attrs[k] = v end
		nd.map = nil
		return n, d
	end
	local map = {}
	local function deep(i)
		local n, d = copy(i)
		map[i] = n
		for _, c in ipairs(d.children) do
			local cc = deep(c)
			setParent(cc, n)
		end
		return n
	end
	local root = deep(self)
	-- re-point references (welds, PrimaryPart, attachments) inside the copy
	for old, new in pairs(map) do
		for k, v in pairs(data[old].props) do
			if TYPE[v] == "Instance" and map[v] then data[new].props[k] = map[v] end
		end
	end
	return root
end
function methods.SetAttribute(self, name, value)
	if type(name) ~= "string" then fail("SetAttribute needs a name", 2) end
	local t = typeof(value)
	if value ~= nil and t ~= "string" and t ~= "number" and t ~= "boolean" and t ~= "Vector3" and t ~= "Color3" and t ~= "CFrame" then
		fail("Attribute " .. name .. " cannot hold a " .. t, 2)
	end
	local d = data[self]
	if d.attrs[name] == value then return end
	d.attrs[name] = value
	fire(sig(self, "AttributeChanged"), name)
	local s = d.attrSignals and d.attrSignals[name]
	if s then fire(s) end
end
function methods.GetAttribute(self, name) return data[self].attrs[name] end
function methods.GetAttributes(self) return table.clone(data[self].attrs) end
function methods.GetAttributeChangedSignal(self, name)
	local d = data[self]
	d.attrSignals = d.attrSignals or {}
	if not d.attrSignals[name] then d.attrSignals[name] = newSignal("attr " .. name) end
	return d.attrSignals[name]
end
function methods.GetPropertyChangedSignal(self, name)
	local d = data[self]
	local m = member(d.class, name)
	if not m or m.k ~= "P" then fail(tostring(name) .. " is not a valid property of " .. describe(self), 2) end
	d.propSignals = d.propSignals or {}
	if not d.propSignals[name] then d.propSignals[name] = newSignal("prop " .. name) end
	return d.propSignals[name]
end
function methods.GetFullName(self) return describe(self) end

-- Class-specific behaviour
local function partsOf(model)
	local out = {}
	for _, c in ipairs(methods.GetDescendants(model)) do
		if isA(data[c].class, "BasePart") then out[#out + 1] = c end
	end
	return out
end
local function pivotOf(model)
	local pp = data[model].props.PrimaryPart
	if pp then return pp.CFrame end
	local parts = partsOf(model)
	if parts[1] then return parts[1].CFrame end
	return CFrame.identity
end
classMethods.Model = {
	GetPivot = function(self) return pivotOf(self) end,
	PivotTo = function(self, cf)
		if typeof(cf) ~= "CFrame" then fail("PivotTo needs a CFrame", 2) end
		local delta = cf * pivotOf(self):Inverse()
		for _, p in ipairs(partsOf(self)) do data[p].props.CFrame = delta * p.CFrame end
	end,
	ScaleTo = function(self, s)
		num(s, "scale")
		local pivot = pivotOf(self)
		for _, p in ipairs(partsOf(self)) do
			local rel = pivot:Inverse() * p.CFrame
			data[p].props.Size = p.Size * s
			data[p].props.CFrame = pivot * mk(rel.px * s, rel.py * s, rel.pz * s, rel.m)
		end
	end,
}
classMethods.BasePart = {
	SetNetworkOwner = function() end,
	PivotTo = function(self, cf) data[self].props.CFrame = cf end,
	GetPivot = function(self) return self.CFrame end,
}
Mock.humanoids = setmetatable({}, { __mode = "k" })
local function newTrack()
	local t = { IsPlaying = false, Looped = true }
	function t.Play(self) self.IsPlaying = true end
	function t.Stop(self) self.IsPlaying = false end
	return t
end
classMethods.Humanoid = {
	MoveTo = function(self, pos)
		if not isV3(pos) then fail("Humanoid:MoveTo needs a Vector3", 2) end
		Mock.humanoids[self] = pos
	end,
	TakeDamage = function(self, n) data[self].props.Health = math.max(0, self.Health - n) end,
	GetAppliedDescription = function(self) return Instance.new("HumanoidDescription") end,
	ApplyDescription = function(self, desc)
		if typeof(desc) ~= "Instance" or data[desc].class ~= "HumanoidDescription" then fail("ApplyDescription needs a HumanoidDescription", 2) end
	end,
	LoadAnimation = function() return newTrack() end,
}
classMethods.HumanoidDescription = {
	GetAccessories = function(self, includeRigid)
		if type(includeRigid) ~= "boolean" then fail("GetAccessories needs true or false", 2) end
		return {
			{ AssetId = 1, AccessoryType = Enum.AccessoryType.Jacket, Order = 1 },
			{ AssetId = 2, AccessoryType = Enum.AccessoryType.Hair, Order = 2 },
		}
	end,
	SetAccessories = function(self, list, includeRigid)
		if type(list) ~= "table" or type(includeRigid) ~= "boolean" then fail("SetAccessories needs a list and true or false", 2) end
		for _, worn in ipairs(list) do
			if typeof(worn.AccessoryType) ~= "EnumItem" then fail("each accessory needs an AccessoryType", 2) end
		end
		Mock.keptAccessories = #list
	end,
}
classMethods.Animator = {
	LoadAnimation = function(self, anim)
		if typeof(anim) ~= "Instance" or data[anim].class ~= "Animation" then fail("LoadAnimation needs an Animation", 2) end
		if not methods.IsDescendantOf(self, game) then fail("LoadAnimation requires the Animator to be in the game", 2) end
		return newTrack()
	end,
}
classMethods.ParticleEmitter = { Emit = function(self, n) num(n, "count") end, Clear = function() end }
classMethods.Terrain = {
	FillBlock = function(self, cf, size, mat)
		if typeof(cf) ~= "CFrame" or typeof(size) ~= "Vector3" or typeof(mat) ~= "EnumItem" or mat.EnumType ~= "Material" then fail("Terrain:FillBlock(CFrame, Vector3, Material) got wrong values", 2) end
		if size[1] <= 0 or size[2] <= 0 or size[3] <= 0 then fail("Terrain:FillBlock with an empty or negative size: " .. tostring(size), 2) end
		table.insert(Mock.terrain, { kind = "block", cf = cf, size = size, mat = mat.Name })
	end,
	FillBall = function(self, pos, r, mat)
		if typeof(pos) ~= "Vector3" or type(r) ~= "number" or typeof(mat) ~= "EnumItem" or mat.EnumType ~= "Material" then fail("Terrain:FillBall(Vector3, number, Material) got wrong values", 2) end
		table.insert(Mock.terrain, { kind = "ball", pos = pos, r = r, mat = mat.Name })
	end,
	FillCylinder = function(self, cf, h, r, mat)
		if typeof(cf) ~= "CFrame" or type(h) ~= "number" or type(r) ~= "number" or typeof(mat) ~= "EnumItem" or mat.EnumType ~= "Material" then fail("Terrain:FillCylinder(CFrame, height, radius, Material) got wrong values", 2) end
		table.insert(Mock.terrain, { kind = "cyl", cf = cf, h = h, r = r, mat = mat.Name })
	end,
}
classMethods.CollectionService = {
	AddTag = function(self, inst, t)
		tags[t] = tags[t] or {}
		tags[t][inst] = true
		data[inst].tags = data[inst].tags or {}
		data[inst].tags[t] = true
		if tagSignals[t] then fire(tagSignals[t], inst) end
	end,
	HasTag = function(self, inst, t) return tags[t] ~= nil and tags[t][inst] == true end,
	GetTagged = function(self, t)
		local out = {}
		for inst in pairs(tags[t] or {}) do out[#out + 1] = inst end
		return out
	end,
	GetInstanceAddedSignal = function(self, t)
		tagSignals[t] = tagSignals[t] or newSignal("tag " .. t)
		return tagSignals[t]
	end,
}
classMethods.Debris = {
	AddItem = function(self, inst, t)
		task.delay(t or 10, function() methods.Destroy(inst) end)
	end,
}
classMethods.TweenService = {
	Create = function(self, inst, info, goals)
		if typeof(inst) ~= "Instance" then fail("TweenService:Create needs an Instance", 2) end
		if typeof(info) ~= "TweenInfo" then fail("TweenService:Create needs a TweenInfo", 2) end
		if type(goals) ~= "table" then fail("TweenService:Create needs a table of goals", 2) end
		for k, v in pairs(goals) do
			local m = member(data[inst].class, k)
			if not m or m.k ~= "P" then fail("Tween goal \"" .. tostring(k) .. "\" is not a property of " .. describe(inst), 2) end
			local problem = checkType(data[inst].class, k, m, v)
			if problem then fail("Tween goal " .. k .. " of " .. describe(inst) .. " must be " .. problem, 2) end
			if m.cat == "Primitive" and m.typ == "bool" then fail("Tween goal " .. k .. " cannot be tweened (true/false)", 2) end
		end
		local tw = { Completed = newSignal("Tween.Completed") }
		function tw.Play()
			task.delay(info.Time, function()
				if not data[inst].destroyed then
					for k, v in pairs(goals) do inst[k] = v end
				end
				fire(tw.Completed)
			end)
		end
		function tw.Cancel() end
		return tw
	end,
}
local stores = {}
classMethods.DataStoreService = {
	GetDataStore = function(self, name)
		stores[name] = stores[name] or {}
		local s = stores[name]
		local store = {}
		function store.GetAsync(_, key) return s[key] end
		function store.SetAsync(_, key, value)
			-- the real service refuses mixed or sparse tables
			local function check(t, path)
				local n, keys = 0, 0
				for k, v in pairs(t) do
					keys = keys + 1
					if type(k) == "number" then n = n + 1 elseif type(k) ~= "string" then error("DataStore: bad key type at " .. path) end
					if type(v) == "table" then check(v, path .. "." .. tostring(k)) elseif type(v) == "function" or type(v) == "userdata" then error("DataStore: cannot store " .. type(v) .. " at " .. path) end
				end
				if n > 0 and (n ~= keys or n ~= #t) then error("DataStore: mixed or sparse table at " .. path) end
			end
			check(value, key)
			s[key] = value
		end
		return store
	end,
}
classMethods.RunService = { IsStudio = function() return true end, IsServer = function() return true end, IsClient = function() return false end }
classMethods.StarterGui = { SetCoreGuiEnabled = function() end, SetCore = function() end }
classMethods.DataModel = {
	GetService = function(self, name)
		local info = classInfo(name)
		if not info or not info.t:find("Service", 1, true) then fail("\"" .. tostring(name) .. "\" is not a service", 2) end
		local found = methods.FindFirstChildOfClass(self, name)
		if found then return found end
		local s = create(name)
		data[s].props.Name = name
		setParent(s, self)
		return s
	end,
	BindToClose = function() end,
}
