-- A stand-in character body with the standard part names.
local R15 = { "Head", "UpperTorso", "LowerTorso", "LeftUpperArm", "LeftLowerArm", "LeftHand", "RightUpperArm", "RightLowerArm", "RightHand",
	"LeftUpperLeg", "LeftLowerLeg", "LeftFoot", "RightUpperLeg", "RightLowerLeg", "RightFoot" }
function Mock.makeRig()
	local model = create("Model")
	local root = create("Part")
	data[root].props.Name = "HumanoidRootPart"
	data[root].props.Size = Vector3.new(2, 2, 1)
	data[root].props.CFrame = CFrame.new(0, 3, 0)
	setParent(root, model)
	for i, name in ipairs(R15) do
		local p = create("MeshPart")
		data[p].props.Name = name
		data[p].props.Size = Vector3.new(1, 1, 1)
		data[p].props.CFrame = CFrame.new(0, 5 - i * 0.3, 0)
		setParent(p, model)
	end
	local hum = create("Humanoid")
	setParent(hum, model)
	local animator = create("Animator")
	setParent(animator, hum)
	data[model].props.PrimaryPart = root
	return model
end
classMethods.Players = {
	GetPlayers = function(self)
		local out = {}
		for _, c in ipairs(data[self].children) do
			if data[c].class == "Player" then out[#out + 1] = c end
		end
		return out
	end,
	CreateHumanoidModelFromDescription = function(self, desc, rigType)
		if typeof(desc) ~= "Instance" or data[desc].class ~= "HumanoidDescription" then fail("needs a HumanoidDescription", 2) end
		if typeof(rigType) ~= "EnumItem" or rigType.EnumType ~= "HumanoidRigType" then fail("needs a HumanoidRigType", 2) end
		return Mock.makeRig()
	end,
	GetPlayerFromCharacter = function(self, model)
		for _, p in ipairs(classMethods.Players.GetPlayers(self)) do
			if data[p].props.Character == model then return p end
		end
		return nil
	end,
}
classMethods.Player = {
	LoadCharacter = function(self)
		local old = data[self].props.Character
		if old then methods.Destroy(old) end
		local model = Mock.makeRig()
		data[model].props.Name = self.Name
		data[self].props.Character = model
		setParent(model, workspace)
		fire(sig(self, "CharacterAdded"), model)
	end,
	HasAppearanceLoaded = function() return true end,
}

----------------------------------------------------------------------
-- The game tree
----------------------------------------------------------------------
game = create("DataModel")
data[game].props.Name = "game"
workspace = game:GetService("Workspace")
do
	local terrain = create("Terrain")
	setParent(terrain, workspace)
	local camera = create("Camera")
	data[camera].props.ViewportSize = Vector2.new(1600, 900)
	setParent(camera, workspace)
	data[workspace].props.CurrentCamera = camera
end

-- Advance simulated time by dt seconds.
function Mock.step(dt)
	Mock.now = Mock.now + dt
	-- move humanoids toward where they were told to go
	for hum, dest in pairs(Mock.humanoids) do
		local d = data[hum]
		local model = d and d.parent
		local root = model and methods.FindFirstChild(model, "HumanoidRootPart")
		if root and not d.destroyed then
			local pos = root.Position
			local flat = Vector3.new(dest[1] - pos[1], 0, dest[3] - pos[3])
			local dist = flat.Magnitude
			local stepLen = hum.WalkSpeed * dt
			if dist > 0.05 and stepLen > 0 then
				local move = flat * (math.min(stepLen, dist) / dist)
				if move[1] ~= move[1] then error("NaN move: " .. tostring(model) .. " speed=" .. tostring(hum.WalkSpeed) .. " dist=" .. tostring(dist) .. " dest=" .. tostring(dest[1]) .. "," .. tostring(dest[3]) .. " pos=" .. tostring(pos[1])) end
				for _, p in ipairs(partsOf(model)) do
					local c = data[p].props.CFrame
					if c then data[p].props.CFrame = mk(c.px + move[1], c.py, c.pz + move[3], c.m) end
				end
			end
		else
			Mock.humanoids[hum] = nil
		end
	end
	local rs = methods.FindFirstChildOfClass(game, "RunService")
	if rs then
		fire(sig(rs, "Heartbeat"), dt)
		fire(sig(rs, "RenderStepped"), dt)
	end
	local due = {}
	local keep = {}
	for _, w in ipairs(waiting) do
		if w.at <= Mock.now then due[#due + 1] = w else keep[#keep + 1] = w end
	end
	waiting = keep
	for _, w in ipairs(due) do resume(w.co, Mock.now - w.start) end
end

function Mock.run(seconds, dt)
	dt = dt or 0.1
	local t = 0
	while t < seconds do
		Mock.step(dt)
		t = t + dt
	end
end

-- Running scripts and require()
local loaded = {}
function Mock.runScript(inst, source, name)
	local env = setmetatable({ script = inst }, { __index = _G, __newindex = function(_, k) error("script tried to create a global named \"" .. tostring(k) .. "\"", 2) end })
	local fn, err = load(source, "=" .. name, "t", env)
	if not fn then
		Mock.errors = Mock.errors + 1
		print("  SYNTAX ERROR: " .. tostring(err))
		return nil
	end
	return fn
end
function require(inst)
	if typeof(inst) ~= "Instance" or data[inst].class ~= "ModuleScript" then fail("require needs a ModuleScript, got " .. typeof(inst), 2) end
	if loaded[inst] ~= nil then return loaded[inst] end
	local fn = Mock.runScript(inst, data[inst].source, data[inst].props.Name)
	if not fn then fail("could not load module " .. tostring(inst), 2) end
	local result = fn()
	if result == nil then fail("module " .. tostring(inst) .. " did not return a value", 2) end
	loaded[inst] = result
	return result
end
Mock.loaded = loaded
Mock.methods = methods
Mock.setParent = setParent

return Mock
